// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address user1, uint256 amount) public {
        vm.assume(user1 != address(0) && address(this) != address(0));
        vm.assume(amount < type(uint256).max);

        uint256 depositAmount = bound(amount, 1, 1 ether);
        vm.deal(user1, depositAmount);
        vm.prank(user1);
        c.deposit{value: depositAmount}();

        uint256 balanceBefore = address(c).balance;
        c.migrateTo(address(0));
        uint256 balanceAfter = address(c).balance;

        assertTrue(balanceBefore > 0 && balanceAfter == 0, "migrateTo should empty contract");
    }
}

